-- 00133_cycle_smart_tip_rules.sql — the cycle home's «نکتهٔ هوشمند» as message rules (D-216, user request
-- 2026-11-28: one decision layer for every message). Data only (no schema change), so no Laravel twin: Laravel
-- never serves the feed.
--
-- One approved smart_tip rule per message of the cycle part of the legacy manager bundle (GET /messages/daily):
-- rule_key tip.cycle.<phase> / tip.ttc.<phase> (the phase message), tip.symptom.<symptom> (today's log) and
-- tip.corr.<insight> (a combination of today's symptoms). The rows are generated from internal/messages/cycletips
-- (Defs: go test ./internal/messages/cycletips -run TestSeedSQL -seed-out=…) and pinned by the migration int test.
-- The copy is the legacy defaults (default language fa as the base, content.translations.en); the conditions read
-- the engine facts and symptoms_today instead of the legacy detectors (dead since D-05). A fertile-window message
-- carries the fertile_window topic (M-06).
-- ON DUPLICATE KEY keeps a database whose rules were already seeded (or edited) as it is.
-- Down removes the seeded rules.
-- +goose Up
-- +goose StatementBegin
INSERT INTO `message_rules` (rule_key, title, level, kind, priority, placement, content, conditions, exceptions, topics,
  variants_enabled, ab_split, cap_count, cap_period, cooldown_days, audience_percent, status, is_active, version,
  approved_version, locked, created_at, updated_at)
VALUES
('tip.corr.sleep_mood', 'Smart tip: sleep mood', 'info', 'clinical', 780, 'smart_tip', '{"a":{"title":"خواب و خلق","body":"کیفیت خواب پایین می‌تونه روی خلق و خو تأثیر بذاره. بهبود خواب ممکنه به بهتر شدن حالت روحی کمک کنه. پیشنهاد: سعی کن امشب زودتر بخوابی و از گوشی قبل خواب استفاده نکنی"},"translations":{"en":{"a":{"title":"Sleep and mood","body":"Poor sleep quality can affect mood. Improving sleep may help improve mood. Try this: Try to sleep earlier tonight and avoid phone before bed"}}}}', '[{"op":"and","items":[{"fact":"mode","op":"in","value":["cycle","ttc"]},{"fact":"symptoms_today","op":"contains","value":"poor_sleep"},{"fact":"symptoms_today","op":"in","value":["mood_sad","mood_angry"]}]}]', '[]', NULL, 0, 50, NULL, NULL, 0, 100, 'approved', 1, 1, 1, 0, NOW(), NOW()),
