DELETE FROM `message_rules` WHERE `rule_key` LIKE 'tip.cycle.%' OR `rule_key` LIKE 'tip.ttc.%'
  OR `rule_key` LIKE 'tip.symptom.%' OR `rule_key` LIKE 'tip.corr.%';
